// Prepare data for the main workflow
const mergedData = $('Merge Bot Token').first().json;
const binaryData = $input.first().binary;

console.log('=== PREPARE FOR MAIN WORKFLOW ===');
console.log('Has binary data:', !!binaryData);
console.log('User ID for DB:', mergedData.user_id);
console.log('Chat ID:', mergedData.chat_id);

// Ensure user_id is available for expense INSERT
// The main workflow should use: INSERT INTO expenses (user_id, chat_id, ...) VALUES ($json.user_id, $json.chat_id, ...)
return {
  json: {
    ...mergedData,
    user_id: mergedData.user_id,  // Database user_id (users.id) - USE THIS FOR EXPENSE INSERTS
    chat_id: mergedData.chat_id,  // Telegram chat_id - keep for backward compatibility
    route_to: 'image',
    is_image: true,
    file_downloaded: true
  },
  binary: binaryData
};

// Handle non-image messages (text, callbacks, commands)
const mergedData = $('Merge Bot Token').first().json;

console.log('=== NON-IMAGE MESSAGE ===');
console.log('Text:', mergedData.text);
console.log('Callback Data:', mergedData.callback_data);
console.log('User ID for DB:', mergedData.user_id);

// Check if this is a callback query (button press)
const isCallback = mergedData.callback_data && mergedData.callback_data.length > 0;

// Check if this is a /start command
const isStartCommand = mergedData.text && mergedData.text.startsWith('/start');

// Route logic:
// - callback queries (button presses like payment method selection) -> 'callback'
// - /start commands -> 'start_command'
// - everything else (text messages, AI queries) -> 'ai_query'
const routeTo = isCallback ? 'callback' : (isStartCommand ? 'start_command' : 'ai_query');

console.log('Routing to:', routeTo);

// Ensure user_id is available for any database operations
return {
  json: {
    ...mergedData,
    user_id: mergedData.user_id,  // Database user_id (users.id)
    chat_id: mergedData.chat_id,  // Telegram chat_id
    route_to: routeTo,
    is_image: false
  }
};
